-- Backend Engineering ("The Fracture") Act 2 -- "The Server" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql).
-- References the world-be-2 spine row already inserted by
-- 20260810045000_backend_acts2_10_and_arc2.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be2', 'world-be-2', 'the-server', '2A - The Server', 'Rebuild the emergency dispatch service on a real runtime instead of patched-together scripts -- and find out why standing one up correctly is harder than it looks.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be2-1', 'campaign-be2', 'first-boot', 'First Boot', 'The runtime, the language and the packages everything else in Forge''s new service stands on.', 1),
  ('operation-be2-2', 'campaign-be2', 'wired-up', 'Wired Up', 'Turning a bare process into a service that can take a request, hold real configuration, and actually stay up.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be2-01', 'world-be-2', 'campaign-be2', 'operation-be2-1', 'runtime-and-process', 'Runtime and Process', 'The hand-rolled fix holds, barely. Forge Division starts rebuilding the emergency dispatch service on a real runtime, and that starts with understanding what a runtime and a process actually are.', 'beginner', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"process-lifecycle-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 1),
  ('mission-be2-02', 'world-be-2', 'campaign-be2', 'operation-be2-1', 'nodejs-introduction', 'Node.js Introduction', 'The specific runtime Forge is standardizing on: V8 underneath, an event loop instead of a browser tab, and APIs a browser was never given.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be2-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"node-runtime-sim"}'::jsonb, '{"xp":95,"credits":15}'::jsonb, false, 2),
  ('mission-be2-03', 'world-be-2', 'campaign-be2', 'operation-be2-1', 'npm-and-packages', 'npm and Packages', 'Nobody writes a real service from nothing. npm is how Forge borrows other people''s code responsibly -- or doesn''t.', 'beginner', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be2-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"npm-packages-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 3),
  ('mission-be2-04', 'world-be-2', 'campaign-be2', 'operation-be2-1', 'typescript-for-backend', 'TypeScript for Backend', 'The exact class of bug that took down the dispatch endpoint last Act -- a string where a boolean belonged -- is precisely what static types exist to catch before it ships.', 'beginner', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be2-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"typescript-types-sim"}'::jsonb, '{"xp":100,"credits":18}'::jsonb, false, 4),
  ('mission-be2-05', 'world-be-2', 'campaign-be2', 'operation-be2-1', 'creating-an-http-server', 'Creating an HTTP Server', 'The actual heartbeat of everything Forge builds from here: a process that listens on a port and answers.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be2-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"http-server-sim"}'::jsonb, '{"xp":105,"credits":18}'::jsonb, false, 5),
  ('mission-be2-06', 'world-be-2', 'campaign-be2', 'operation-be2-1', 'routing', 'Routing', 'One growing if/else chain is already routing every dispatch request. It won''t survive contact with a second route, let alone twenty.', 'beginner', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be2-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"routing-table-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 6),
  ('mission-be2-07', 'world-be-2', 'campaign-be2', 'operation-be2-2', 'request-parameters', 'Request Parameters', 'The route matches. Now the handler has to actually read which ambulance unit the path is talking about.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be2-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"route-params-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 7),
  ('mission-be2-08', 'world-be-2', 'campaign-be2', 'operation-be2-2', 'query-parameters', 'Query Parameters', 'Filtering the dispatch list by status, priority or limit -- all of it riding in the part of the URL after the question mark.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be2-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"query-params-sim"}'::jsonb, '{"xp":125,"credits":20}'::jsonb, false, 8),
  ('mission-be2-09', 'world-be-2', 'campaign-be2', 'operation-be2-2', 'request-bodies', 'Request Bodies', 'A request body doesn''t arrive as one neat object. It arrives the way everything in Node arrives: in pieces, over time.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be2-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"request-body-sim"}'::jsonb, '{"xp":130,"credits":22}'::jsonb, false, 9),
  ('mission-be2-10', 'world-be-2', 'campaign-be2', 'operation-be2-2', 'environment-variables', 'Environment Variables', 'A database password committed directly into a file that lives in the shared repository. Forge wants it gone -- into the environment, not the code.', 'intermediate', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be2-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"env-vars-sim"}'::jsonb, '{"xp":130,"credits":22}'::jsonb, false, 10),
  ('mission-be2-11', 'world-be-2', 'campaign-be2', 'operation-be2-2', 'configuration', 'Configuration', 'Forty scattered reads of process.env is how a service starts successfully with half its configuration quietly missing. Forge wants one place that checks, once.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be2-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"config-layer-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 11),
  ('mission-be2-12', 'world-be-2', 'campaign-be2', 'operation-be2-2', 'port-8080', 'Port 8080', 'The first real deploy of the new service. The process logs a clean startup. The dispatch client can''t reach it at all.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be2-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"port-8080-boss-sim"}'::jsonb, '{"xp":380,"credits":80,"badgeIds":["port-8080"],"skillXp":{"backend_fundamentals":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be2-01', 1, 'mira', 'The hand-rolled fix on the emergency endpoint held. Barely. It''s bash scripts and cron jobs keeping something alive that answers life-or-death requests. That ends now -- we''re rebuilding it on a real runtime.'),
  ('mission-be2-01', 2, 'forge', 'Everything you''ve run so far -- every script -- already ran inside something. A runtime, executing one process at a time, with the operating system deciding when it actually gets the CPU.'),
  ('mission-be2-01', 3, 'forge', 'A process is a program actually running: its own memory, its own copy of the environment, a start, and eventually an exit. Node.js is a runtime that lets you write that process in JavaScript instead of C.'),
  ('mission-be2-01', 4, 'mira', 'Get this distinction wrong and you''ll blame ''the code'' for things that are actually the process crashing, restarting, or never starting in the first place. Learn the boundary first.'),
  ('mission-be2-02', 1, 'forge', 'Node.js takes V8 -- the same engine that runs JavaScript inside Chrome -- and wraps it with what a server actually needs: a filesystem, a network stack, and an event loop instead of a browser tab.'),
  ('mission-be2-02', 2, 'forge', 'No DOM, no window object. Instead you get process, a module system, and direct access to the machine underneath. Different job, different toolbox.'),
  ('mission-be2-03', 1, 'forge', 'npm ships with Node and does two jobs at once: it''s a registry of other people''s code, and it''s the thing that remembers exactly which versions your project actually needs.'),
  ('mission-be2-03', 2, 'mira', 'Every dependency you add is code Forge didn''t write and now has to trust anyway. Pin your versions. Read what you''re actually installing.'),
  ('mission-be2-04', 1, 'mira', 'Last Act, a dispatch response sent ''true'' as a string instead of a real boolean, and a client''s check silently passed when it should have failed. That bug shipped because nothing checked the shape of the data until it was already live.'),
  ('mission-be2-04', 2, 'forge', 'TypeScript won''t stop a bad response from a server you don''t control. It will absolutely stop your own code from building that exact response in the first place -- at compile time, before Node ever sees it.'),
  ('mission-be2-05', 1, 'forge', 'This is the actual heartbeat of everything we build from here: a process that binds to a port, and a function that runs once per request that arrives on it.'),
  ('mission-be2-05', 2, 'forge', 'Everything else -- routing, parsing, auth, all of it -- is just more code running inside this one handler function. Get the shape of this right and it scales. Get it wrong and everything built on top inherits the mistake.'),
  ('mission-be2-06', 1, 'forge', 'Right now every request is matched by one growing if/else chain. It already has six branches. It won''t survive a twentieth route.'),
  ('mission-be2-06', 2, 'mira', 'This is exactly how The Request happened -- code that works today and becomes unreadable, then unreliable, within a week. Build the route table properly the first time.'),
  ('mission-be2-07', 1, 'forge', 'The route matches now. The handler still has to actually read which unit the path is talking about -- and every piece of it arrives as plain text, whether it looks like a number or not.'),
  ('mission-be2-08', 1, 'forge', 'Everything after the question mark in a URL is the query string -- filters, pagination, options, all optional by convention, none of it guaranteed to actually be there.'),
  ('mission-be2-09', 1, 'forge', 'A request body doesn''t show up as one neat object waiting for you. It arrives the way everything does in Node: in pieces, over time, and you find out it''s finished the same way you''d find out anything else finished -- an event fires.'),
  ('mission-be2-09', 2, 'mira', 'Get impatient with that and you''ll parse a body that hasn''t fully arrived yet. We''ll come back to streams properly next Act.'),
  ('mission-be2-10', 1, 'mira', 'Found this in the file that handles the dispatch endpoint''s database connection: a real password, written directly into source code that''s been committed to the shared repository fourteen times.'),
  ('mission-be2-10', 2, 'forge', 'That password is now part of this repository''s history forever, identical in every environment, readable by anyone with checkout access. Environment variables exist specifically so this never has to happen.'),
  ('mission-be2-11', 1, 'forge', 'Right now, config is process.env.WHATEVER, scattered across forty files, read wherever someone happened to need it. Nothing checks any of it actually exists before the server claims to be ready.'),
  ('mission-be2-11', 2, 'mira', 'That''s not paranoia. That''s exactly the shape of bug that''s about to happen to us.'),
  ('mission-be2-12', 1, 'mira', 'First real deploy of the new service. The process logs a clean startup -- no errors, no crash. The dispatch client gets connection refused on every single request.'),
  ('mission-be2-12', 2, 'forge', 'I''ve pulled the startup log and the actual listener code. Something in here is lying about being ready, and I want you to find exactly what, not just that something''s wrong.'),
  ('mission-be2-12', 3, 'mira', 'Don''t patch it blind. Trace it the way you''ve traced everything else this Act -- evidence first, then the line, then the fix.'),
  ('mission-be2-12', 4, 'forge', '...one more thing, buried three lines above the crash we''re chasing. The route table registers a path as ''//health'' -- two slashes, not one. Nobody typed that. The service starts fine either way.'),
  ('mission-be2-12', 5, 'mira', 'Noted. File it next to the doubled slash from the silent endpoint. That''s twice now. We''re not chasing it today -- but I don''t think it''s nothing, either.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be2-01-o1', 'mission-be2-01', 1, 'Name the layer', 'Tell a program apart from the process it becomes once it''s actually running.'),
  ('mission-be2-01-o2', 'mission-be2-01', 2, 'Judge the restart', 'Decide whether restarting a crashed process actually counts as recovering from the crash.'),
  ('mission-be2-02-o1', 'mission-be2-02', 1, 'Define the runtime', 'Say precisely what Node.js actually is.'),
  ('mission-be2-02-o2', 'mission-be2-02', 2, 'Match the pieces', 'Match each part of the runtime to the job it actually does.'),
  ('mission-be2-03-o1', 'mission-be2-03', 1, 'Read the version range', 'Decide exactly what a semver range actually allows npm to install.'),
  ('mission-be2-03-o2', 'mission-be2-03', 2, 'Explain the missing package', 'Find why a package that exists in development disappears in production.'),
  ('mission-be2-04-o1', 'mission-be2-04', 1, 'Find the type error', 'TypeScript refuses to compile this. Find the line it flags.'),
  ('mission-be2-04-o2', 'mission-be2-04', 2, 'Know the limit', 'Decide what static types can and can''t actually protect you from.'),
  ('mission-be2-05-o1', 'mission-be2-05', 1, 'Find the ordering bug', 'The response never actually completes correctly. Find the line that runs too late to matter.'),
  ('mission-be2-05-o2', 'mission-be2-05', 2, 'Explain listen()', 'Say precisely what server.listen(8080) actually does.'),
  ('mission-be2-06-o1', 'mission-be2-06', 1, 'Match the route', 'Match each incoming request to the route table entry that should handle it.'),
  ('mission-be2-06-o2', 'mission-be2-06', 2, 'Diagnose the shadowed route', 'Find why a specific route never reaches the handler it was written for.'),
  ('mission-be2-07-o1', 'mission-be2-07', 1, 'Find the comparison bug', 'The lookup always fails. Find the line responsible.'),
  ('mission-be2-07-o2', 'mission-be2-07', 2, 'Decide how to validate', 'Decide what a route should do when its path parameter doesn''t look valid at all.'),
  ('mission-be2-08-o1', 'mission-be2-08', 1, 'Read repeated keys', 'Know what a repeated query key actually becomes once it''s parsed.'),
  ('mission-be2-08-o2', 'mission-be2-08', 2, 'Diagnose the empty list', 'Find why omitting a query parameter breaks the default behavior.'),
  ('mission-be2-09-o1', 'mission-be2-09', 1, 'Find the premature parse', 'Find the line that runs before the request body has actually finished arriving.'),
  ('mission-be2-09-o2', 'mission-be2-09', 2, 'Explain why bodies stream', 'Say why Node can''t just hand a handler the whole parsed body as one argument.'),
  ('mission-be2-10-o1', 'mission-be2-10', 1, 'Find the exposed secret', 'Find the root cause of the leak, not just a symptom of it.'),
  ('mission-be2-10-o2', 'mission-be2-10', 2, 'Explain the real cost', 'Explain what''s actually wrong with hardcoding a secret, beyond ''someone might see it.'''),
  ('mission-be2-11-o1', 'mission-be2-11', 1, 'Find the false success', 'Find the line that lets the server claim success no matter what its configuration actually is.'),
  ('mission-be2-11-o2', 'mission-be2-11', 2, 'State the fix', 'Say what Forge actually wants before this configuration pattern ships.'),
  ('mission-be2-12-o1', 'mission-be2-12', 1, 'Read the incident', 'Find the evidence that explains why the server reports success but can''t actually be reached.'),
  ('mission-be2-12-o2', 'mission-be2-12', 2, 'Find the line', 'Find the exact line that reads the environment before it''s actually loaded.'),
  ('mission-be2-12-o3', 'mission-be2-12', 3, 'Rule out the decoy', 'Judge a competing theory against the actual evidence.'),
  ('mission-be2-12-o4', 'mission-be2-12', 4, 'Fix the config', 'State the fix, tying the investigation, the code and the ruled-out theory together.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be2-01-o1-c1', 'mission-be2-01-o1', 1, 'multiple_choice', 'Forge says the process crashed, not the code. What''s the actual difference between a program and a process?', '{"question":"Forge says the process crashed, not the code. What''s the actual difference between a program and a process?","options":[{"id":"a","text":"They''re the same thing, just different words for it"},{"id":"b","text":"A program is the code sitting on disk; a process is that program actually running, with its own memory and state, started by the runtime"},{"id":"c","text":"A process is the code on disk; a program is it running"},{"id":"d","text":"A program can only ever produce one process, ever"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be2-01-o2-c1', 'mission-be2-01-o2', 1, 'investigation', 'Which piece of evidence best explains why simply restarting the process isn''t actually a safe recovery here?', '{"evidence":[{"id":"ev1","label":"Process monitor log","detail":"emergency-dispatch.sh exited with code 1, restarted by cron 4 seconds later"},{"id":"ev2","label":"In-memory state","detail":"3 pending dispatch requests were held only in memory and were lost the moment the process exited"},{"id":"ev3","label":"Exit code","detail":"Exit code 1 is written to the log but nothing downstream ever reads it"}],"question":"Which piece of evidence best explains why simply restarting the process isn''t actually a safe recovery here?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be2-02-o1-c1', 'mission-be2-02-o1', 1, 'multiple_choice', 'What actually is Node.js?', '{"question":"What actually is Node.js?","options":[{"id":"a","text":"A programming language"},{"id":"b","text":"A framework for building websites"},{"id":"c","text":"A JavaScript runtime built on Chrome''s V8 engine, plus APIs for the filesystem, network and OS that a browser never exposes"},{"id":"d","text":"A database"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be2-02-o2-c1', 'mission-be2-02-o2', 1, 'drag_and_drop', 'Match each part of the runtime to the job it actually does.', '{"items":[{"id":"v8","text":"V8"},{"id":"eventloop","text":"The event loop"},{"id":"processglobal","text":"The global process object"},{"id":"modules","text":"require() / import"}],"targets":[{"id":"t1","label":"Executes your JavaScript at native speed"},{"id":"t2","label":"Lets Node handle many connections on one thread without blocking"},{"id":"t3","label":"Gives your code access to arguments, environment variables, and a way to exit"},{"id":"t4","label":"Loads other files as reusable code"}]}'::jsonb, '{"correctMapping":{"v8":"t1","eventloop":"t2","processglobal":"t3","modules":"t4"}}'::jsonb),

  ('mission-be2-03-o1-c1', 'mission-be2-03-o1', 1, 'multiple_choice', 'package.json lists express as "^4.2.1". What does the caret actually allow npm to install?', '{"question":"package.json lists express as \"^4.2.1\". What does the caret actually allow npm to install?","options":[{"id":"a","text":"Only exactly 4.2.1"},{"id":"b","text":"Any version at all, including 5.x"},{"id":"c","text":"Any 4.x.x version that is at least 4.2.1, but never 5.0.0"},{"id":"d","text":"Any 4.2.x version only, never 4.3.0"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be2-03-o2-c1', 'mission-be2-03-o2', 1, 'investigation', 'Which pieces of evidence together explain why the production server can''t find nodemon?', '{"evidence":[{"id":"ev1","label":"Deploy log","detail":"Error: Cannot find module ''nodemon''"},{"id":"ev2","label":"package.json","detail":"nodemon is listed under devDependencies, not dependencies"},{"id":"ev3","label":"Deploy script","detail":"Production install runs with --omit=dev before the service starts"}],"question":"Which pieces of evidence together explain why the production server can''t find nodemon?"}'::jsonb, '{"requiredEvidenceIds":["ev2","ev3"]}'::jsonb),

  ('mission-be2-04-o1-c1', 'mission-be2-04-o1', 1, 'code_debugging', 'TypeScript refuses to compile this. Which line does it actually flag, and why?', '{"language":"typescript","code":"interface DispatchResponse {\n  status: \"ok\" | \"error\";\n  dispatched: boolean;\n  etaMinutes: number;\n}\n\nconst response: DispatchResponse = {\n  status: \"ok\",\n  dispatched: \"true\",\n  etaMinutes: 4,\n};","question":"TypeScript refuses to compile this. Which line does it actually flag, and why?"}'::jsonb, '{"requiredLineIds":["  dispatched: \"true\","]}'::jsonb),
  ('mission-be2-04-o2-c1', 'mission-be2-04-o2', 1, 'multiple_choice', 'TypeScript catches that exact bug at compile time. What does it NOT protect you from?', '{"question":"TypeScript catches that exact bug at compile time. What does it NOT protect you from?","options":[{"id":"a","text":"Passing a string literal where a number is declared in your own code"},{"id":"b","text":"A third-party API actually sending a string at runtime in a field your interface types as boolean"},{"id":"c","text":"Both a and b equally"},{"id":"d","text":"Neither -- TypeScript catches everything at runtime too"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be2-05-o1-c1', 'mission-be2-05-o1', 1, 'code_debugging', 'Clients connect, but every response ships without the header Forge expects, and sometimes throws entirely. Which line runs too late to have any effect?', '{"language":"javascript","code":"import { createServer } from \"node:http\";\n\nconst server = createServer((req, res) => {\n  res.end(JSON.stringify({ status: \"ok\" }));\n  res.writeHead(200, { \"Content-Type\": \"application/json\" });\n});\n\nserver.listen(8080);","question":"Clients connect, but every response ships without the header Forge expects, and sometimes throws entirely. Which line runs too late to have any effect?"}'::jsonb, '{"requiredLineIds":["  res.writeHead(200, { \"Content-Type\": \"application/json\" });"]}'::jsonb),
  ('mission-be2-05-o2-c1', 'mission-be2-05-o2', 1, 'multiple_choice', 'What does calling server.listen(8080) actually do?', '{"question":"What does calling server.listen(8080) actually do?","options":[{"id":"a","text":"Executes the handler function immediately, once"},{"id":"b","text":"Starts a database on port 8080"},{"id":"c","text":"Binds the process to port 8080 and begins accepting incoming TCP connections, invoking the handler once per request that arrives"},{"id":"d","text":"Sends an HTTP request to port 8080"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be2-06-o1-c1', 'mission-be2-06-o1', 1, 'drag_and_drop', 'Match each incoming request to the route table entry that should handle it.', '{"items":[{"id":"r1","text":"GET /dispatch/12"},{"id":"r2","text":"POST /dispatch"},{"id":"r3","text":"DELETE /dispatch/12"},{"id":"r4","text":"GET /health"}],"targets":[{"id":"t1","label":"GET /dispatch/:id -> getDispatch"},{"id":"t2","label":"POST /dispatch -> createDispatch"},{"id":"t3","label":"DELETE /dispatch/:id -> cancelDispatch"},{"id":"t4","label":"GET /health -> healthCheck"}]}'::jsonb, '{"correctMapping":{"r1":"t1","r2":"t2","r3":"t3","r4":"t4"}}'::jsonb),
  ('mission-be2-06-o2-c1', 'mission-be2-06-o2', 1, 'investigation', 'Which piece of evidence explains why /dispatch/active never reaches the handler written for it?', '{"evidence":[{"id":"ev1","label":"Route table order","detail":"app.get(\"/dispatch/:id\", ...) is registered before app.get(\"/dispatch/active\", ...)"},{"id":"ev2","label":"Client report","detail":"GET /dispatch/active returns a single dispatch record for id \"active\" instead of the active-list logic"},{"id":"ev3","label":"Server log","detail":"No error is thrown -- a handler runs and returns a response either way"}],"question":"Which piece of evidence explains why /dispatch/active never reaches the handler written for it?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be2-07-o1-c1', 'mission-be2-07-o1', 1, 'code_debugging', 'dispatches holds records with numeric ids, and this route always returns nothing found, even for ids that definitely exist. Which line is the actual bug?', '{"language":"javascript","code":"app.get(\"/dispatch/:id\", (req, res) => {\n  const id = req.params.id;\n  const dispatch = dispatches.find((d) => d.id === id);\n  res.json(dispatch);\n});","question":"dispatches holds records with numeric ids, and this route always returns nothing found, even for ids that definitely exist. Which line is the actual bug?"}'::jsonb, '{"requiredLineIds":["  const dispatch = dispatches.find((d) => d.id === id);"]}'::jsonb),
  ('mission-be2-07-o2-c1', 'mission-be2-07-o2', 1, 'multiple_choice', 'A request comes in for GET /dispatch/abc, where "abc" isn''t a valid id in any format the service uses. What should the handler do?', '{"question":"A request comes in for GET /dispatch/abc, where \"abc\" isn''t a valid id in any format the service uses. What should the handler do?","options":[{"id":"a","text":"Let it silently return undefined or null"},{"id":"b","text":"Trust it, since the route already matched"},{"id":"c","text":"Validate the parameter''s shape and return a proper 400 response if it doesn''t fit"},{"id":"d","text":"Crash the entire process"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be2-08-o1-c1', 'mission-be2-08-o1', 1, 'multiple_choice', 'GET /dispatch?status=critical&status=high -- what do you actually get back from most query-parsing libraries for status?', '{"question":"GET /dispatch?status=critical&status=high -- what do you actually get back from most query-parsing libraries for status?","options":[{"id":"a","text":"Just \"critical\""},{"id":"b","text":"Just \"high\", since the second one overwrites the first"},{"id":"c","text":"An array: [\"critical\", \"high\"]"},{"id":"d","text":"A parsing error"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be2-08-o2-c1', 'mission-be2-08-o2', 1, 'investigation', 'Which piece of evidence actually explains the empty-array bug when no limit is supplied?', '{"evidence":[{"id":"ev1","label":"Handler code","detail":"const limit = parseInt(req.query.limit); dispatches.slice(0, limit)"},{"id":"ev2","label":"Request log","detail":"GET /dispatch with no limit given returns an empty array every single time"},{"id":"ev3","label":"Runtime check","detail":"parseInt(undefined) evaluates to NaN, and slice(0, NaN) returns an empty array"}],"question":"Which piece of evidence actually explains the empty-array bug when no limit is supplied?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be2-09-o1-c1', 'mission-be2-09-o1', 1, 'code_debugging', 'This throws a parse error on every request with a body, even well-formed ones. Which line runs before the body has actually finished arriving?', '{"language":"javascript","code":"const server = createServer((req, res) => {\n  let body = \"\";\n  req.on(\"data\", (chunk) => {\n    body += chunk;\n  });\n  const parsed = JSON.parse(body);\n  res.end(JSON.stringify({ received: parsed }));\n});","question":"This throws a parse error on every request with a body, even well-formed ones. Which line runs before the body has actually finished arriving?"}'::jsonb, '{"requiredLineIds":["  const parsed = JSON.parse(body);"]}'::jsonb),
  ('mission-be2-09-o2-c1', 'mission-be2-09-o2', 1, 'multiple_choice', 'Why can''t Node just hand the handler the whole parsed body as one ready-made argument, the way it hands over route params?', '{"question":"Why can''t Node just hand the handler the whole parsed body as one ready-made argument, the way it hands over route params?","options":[{"id":"a","text":"It could, but nobody has built that yet"},{"id":"b","text":"The body arrives over the network as a stream of chunks over time -- Node has no way to know it''s complete until the client signals it''s finished sending"},{"id":"c","text":"Bodies are always empty, for security reasons"},{"id":"d","text":"Only GET requests are allowed to have bodies"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be2-10-o1-c1', 'mission-be2-10-o1', 1, 'investigation', 'Which piece of evidence is the actual root cause of the exposure, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"server.ts","detail":"const DB_PASSWORD = \"forge-temp-2024\";"},{"id":"ev2","label":"git log","detail":"This file has been committed to the shared repository 14 times"},{"id":"ev3","label":"Codebase search","detail":"process.env.DB_PASSWORD is read nowhere in the codebase"}],"question":"Which piece of evidence is the actual root cause of the exposure, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),
  ('mission-be2-10-o2-c1', 'mission-be2-10-o2', 1, 'multiple_choice', 'What''s actually wrong with hardcoding a secret directly into a source file, even in a private repository?', '{"question":"What''s actually wrong with hardcoding a secret directly into a source file, even in a private repository?","options":[{"id":"a","text":"Nothing, as long as the repository stays private"},{"id":"b","text":"It becomes part of the codebase''s permanent history, identical across every environment, and visible to anyone with read access -- forever, even after it''s ''removed'' later"},{"id":"c","text":"It makes the code run measurably slower"},{"id":"d","text":"TypeScript refuses to compile hardcoded strings"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be2-11-o1-c1', 'mission-be2-11-o1', 1, 'code_debugging', 'Every one of these environment variables could be missing and this still prints a clean success message. Which line is the one making that false promise?', '{"language":"javascript","code":"export const config = {\n  port: process.env.PORT,\n  databaseUrl: process.env.DATABASE_URL,\n  notifyApiKey: process.env.NOTIFY_API_KEY,\n};\n\nconst server = createServer(handleRequest);\nserver.listen(config.port, () => {\n  console.log(\"Server started\");\n});","question":"Every one of these environment variables could be missing and this still prints a clean success message. Which line is the one making that false promise?"}'::jsonb, '{"requiredLineIds":["  console.log(\"Server started\");"]}'::jsonb),
  ('mission-be2-11-o2-c1', 'mission-be2-11-o2', 1, 'multiple_choice', 'What''s the fix Forge wants before this ships?', '{"question":"What''s the fix Forge wants before this ships?","options":[{"id":"a","text":"Nothing -- undefined values will sort themselves out later"},{"id":"b","text":"Validate that every required piece of config exists and is well-formed once, at startup, and fail loudly if it doesn''t"},{"id":"c","text":"Wrap every process.env read in its own try/catch block"},{"id":"d","text":"Hardcode fallback values for everything, including secrets"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be2-12-o1-c1', 'mission-be2-12-o1', 1, 'investigation', 'Which piece of evidence explains why the process claims success while being completely unreachable on port 8080?', '{"evidence":[{"id":"ev1","label":"Process log","detail":"Server running on port undefined -- no errors, no stack trace, process stays alive"},{"id":"ev2","label":"Startup code order","detail":"const port = process.env.PORT; is read on the very first line, before dotenv.config() is called two lines later"},{"id":"ev3","label":"Monitoring probe","detail":"Health check against port 8080 returns ECONNREFUSED, immediately, on every attempt"}],"question":"Which piece of evidence explains why the process claims success while being completely unreachable on port 8080?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be2-12-o2-c1', 'mission-be2-12-o2', 1, 'code_debugging', 'Which line executes before the environment variable it depends on has actually been loaded?', '{"language":"javascript","code":"import { createServer } from \"node:http\";\nimport dotenv from \"dotenv\";\n\nconst port = process.env.PORT;\n\ndotenv.config();\n\nconst server = createServer(handleRequest);\nserver.listen(port, () => {\n  console.log(\"Server running on port \" + port);\n});","question":"Which line executes before the environment variable it depends on has actually been loaded?"}'::jsonb, '{"requiredLineIds":["const port = process.env.PORT;"]}'::jsonb),
  ('mission-be2-12-o3-c1', 'mission-be2-12-o3', 1, 'multiple_choice', 'A teammate suggests the server failed to bind because another process already held port 8080. Does the evidence support that?', '{"question":"A teammate suggests the server failed to bind because another process already held port 8080. Does the evidence support that?","options":[{"id":"a","text":"Yes -- any bind failure means the port was already in use"},{"id":"b","text":"No -- a port already in use throws an EADDRINUSE error at startup and the process typically exits; this log shows no error at all, and a listener that started successfully on some port"},{"id":"c","text":"Unknowable without restarting the server"},{"id":"d","text":"Yes, because health checks are failing"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be2-12-o4-c1', 'mission-be2-12-o4', 1, 'boss_encounter', 'Having traced the evidence, the exact line, and ruled out the wrong theory, state the fix.', '{"stages":[{"objectiveRef":"mission-be2-12-o1","label":"Read the incident"},{"objectiveRef":"mission-be2-12-o2","label":"Find the line"},{"objectiveRef":"mission-be2-12-o3","label":"Rule out the decoy"}],"task":"Having traced the evidence, the exact line, and ruled out the wrong theory, state the fix: load environment variables before anything reads them, and never let a listen() callback claim success without knowing the config value it actually needed."}'::jsonb, '{"requiredObjectiveIds":["mission-be2-12-o1","mission-be2-12-o2","mission-be2-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be2-01-o1-c1', 'orientation', 'Notice that Forge blames ''the process,'' not ''the file.'' That word choice is the clue.', 10, 1),
  ('mission-be2-01-o1-c1', 'concept', 'The code on disk never changes on its own. What changes, crashes, and restarts is the running instance of it.', 20, 2),
  ('mission-be2-01-o1-c1', 'solution', 'A program is static code; a process is that code loaded into memory and actually executing, with its own state that the runtime tracks and can end.', 30, 3),
  ('mission-be2-01-o2-c1', 'orientation', 'A restart only recovers what got saved somewhere durable before the crash.', 10, 1),
  ('mission-be2-01-o2-c1', 'concept', 'Anything held only in a variable in memory dies the instant the process does -- a fast restart doesn''t change that.', 20, 2),
  ('mission-be2-01-o2-c1', 'solution', 'ev2: the three pending requests only ever existed in memory, so restarting the process didn''t recover them -- it erased them.', 30, 3),

  ('mission-be2-02-o1-c1', 'orientation', 'Node isn''t a new language -- it''s still JavaScript.', 10, 1),
  ('mission-be2-02-o1-c1', 'solution', 'Node.js is a runtime: V8 to execute JavaScript, plus APIs (filesystem, network, OS) that only make sense outside a browser.', 20, 2),
  ('mission-be2-02-o2-c1', 'orientation', 'One of these four is specifically what makes Node good at handling thousands of connections without spinning up thousands of threads.', 10, 1),
  ('mission-be2-02-o2-c1', 'concept', 'Separate ''what runs the code'' from ''what the code can reach once it''s running.''', 20, 2),
  ('mission-be2-02-o2-c1', 'solution', 'V8 executes; the event loop handles concurrency; process exposes the running environment; require()/import load other files as modules.', 30, 3),

  ('mission-be2-03-o1-c1', 'orientation', 'The caret and the tilde allow different amounts of movement -- and neither allows a major version bump.', 10, 1),
  ('mission-be2-03-o1-c1', 'concept', 'Semver is major.minor.patch. A caret allows minor and patch increases, never a major one.', 20, 2),
  ('mission-be2-03-o1-c1', 'solution', '^4.2.1 allows anything from 4.2.1 up to, but not including, 5.0.0.', 30, 3),
  ('mission-be2-03-o2-c1', 'orientation', 'Nothing here is a bug in nodemon itself -- it''s about which list it''s on and what the deploy script actually installs.', 10, 1),
  ('mission-be2-03-o2-c1', 'concept', 'devDependencies exist for local tooling; a production install that omits dev dependencies won''t bring them along on purpose.', 20, 2),
  ('mission-be2-03-o2-c1', 'solution', 'nodemon was only ever meant for local development (ev2), and the production install explicitly skips dev dependencies (ev3) -- so it was never going to be there.', 30, 3),

  ('mission-be2-04-o1-c1', 'orientation', 'Read the interface first -- it''s the contract everything below has to match.', 10, 1),
  ('mission-be2-04-o1-c1', 'concept', 'dispatched is typed as boolean. A quoted value is always a string, never a boolean, no matter what word is inside the quotes.', 20, 2),
  ('mission-be2-04-o1-c1', 'tool_direction', 'Compare each property''s value against its declared type in the interface, one line at a time.', 30, 3),
  ('mission-be2-04-o1-c1', 'solution', 'dispatched: "true" assigns a string to a property typed boolean -- TypeScript flags that exact line at compile time.', 40, 4),
  ('mission-be2-04-o2-c1', 'orientation', 'Types are erased once the code compiles down to plain JavaScript -- they don''t travel over the network.', 10, 1),
  ('mission-be2-04-o2-c1', 'solution', 'TypeScript checks your own code against its own declared types at compile time. It has no way to verify what an external server actually sends at runtime -- that data could still be wrong.', 20, 2),

  ('mission-be2-05-o1-c1', 'orientation', 'res.end() doesn''t just send data -- it finishes the response.', 10, 1),
  ('mission-be2-05-o1-c1', 'concept', 'Once a response is marked finished, setting headers on it afterward is either ignored or throws -- headers have to go out with or before the body, never after.', 20, 2),
  ('mission-be2-05-o1-c1', 'solution', 'res.writeHead(...) runs after res.end() has already closed out the response -- reorder it so headers are set before the body is sent.', 30, 3),
  ('mission-be2-05-o2-c1', 'orientation', 'Recall the TCP handshake from last Act -- listen() is what makes a process reachable that way at all.', 10, 1),
  ('mission-be2-05-o2-c1', 'solution', 'listen(8080) binds the process to port 8080 and starts accepting TCP connections there; the handler runs once for every request that arrives on it.', 20, 2),

  ('mission-be2-06-o1-c1', 'orientation', 'Match the HTTP method first, then the path shape.', 10, 1),
  ('mission-be2-06-o1-c1', 'solution', 'r1->t1, r2->t2, r3->t3, r4->t4 -- method and path together decide the match, nothing else.', 20, 2),
  ('mission-be2-06-o2-c1', 'orientation', 'Both routes technically match the same request. Ask which one gets asked first.', 10, 1),
  ('mission-be2-06-o2-c1', 'concept', 'A route table is checked in order -- the first pattern that matches wins, even if a more specific one was registered later.', 20, 2),
  ('mission-be2-06-o2-c1', 'solution', 'ev1: the wildcard-shaped /dispatch/:id was registered before the specific /dispatch/active, so it matches first every time and the specific route never gets a turn.', 30, 3),

  ('mission-be2-07-o1-c1', 'orientation', 'req.params.id is never anything but a string, no matter what the path segment looks like.', 10, 1),
  ('mission-be2-07-o1-c1', 'concept', '=== compares both value and type. A string id will never strictly equal a numeric id, even when they ''look the same.''', 20, 2),
  ('mission-be2-07-o1-c1', 'solution', 'd.id === id compares a number to a string with strict equality, which is always false -- convert one side (e.g. Number(id)) before comparing.', 30, 3),
  ('mission-be2-07-o2-c1', 'orientation', 'The route matching successfully only proves the path shape was right -- it says nothing about the value inside it.', 10, 1),
  ('mission-be2-07-o2-c1', 'solution', 'Validate the parameter and respond with a 400 for a malformed id -- silently returning nothing, or worse, crashing, are both worse outcomes than a clear rejection.', 20, 2),

  ('mission-be2-08-o1-c1', 'orientation', 'Query strings don''t have a built-in concept of ''overwrite'' -- both instances of the key are still there.', 10, 1),
  ('mission-be2-08-o1-c1', 'solution', 'Repeated query keys become an array, in the order they appeared: ["critical","high"].', 20, 2),
  ('mission-be2-08-o2-c1', 'orientation', 'Nothing here throws an error -- the bug hides behind a value that''s silently wrong, not a crash.', 10, 1),
  ('mission-be2-08-o2-c1', 'concept', 'parseInt on a value that isn''t there at all doesn''t default to anything sensible -- it produces NaN, and NaN behaves unpredictably in arithmetic and array methods.', 20, 2),
  ('mission-be2-08-o2-c1', 'solution', 'ev3: parseInt(undefined) is NaN, and array.slice(0, NaN) returns an empty array -- the missing default is the actual bug, not the client leaving the parameter off.', 30, 3),

  ('mission-be2-09-o1-c1', 'orientation', 'The data event fires once per chunk. Something here only makes sense to run once, after every chunk has arrived.', 10, 1),
  ('mission-be2-09-o1-c1', 'concept', 'JSON.parse needs the complete string. Called right after registering the data listener, body is still whatever it was at that instant -- often still empty.', 20, 2),
  ('mission-be2-09-o1-c1', 'solution', 'const parsed = JSON.parse(body); runs synchronously, immediately after the listener is registered, long before any chunks -- let alone the end event -- have actually arrived.', 30, 3),
  ('mission-be2-09-o2-c1', 'orientation', 'Recall TCP from last Act: data arrives as a stream of packets, not as one delivery.', 10, 1),
  ('mission-be2-09-o2-c1', 'solution', 'A request body is a stream of chunks over an open connection -- Node only knows it''s complete when the client finishes sending and the connection signals ''end,'' so it can''t hand over a finished value any sooner than that.', 20, 2),

  ('mission-be2-10-o1-c1', 'orientation', 'The other two pieces of evidence describe how bad the exposure is, not why it exists in the first place.', 10, 1),
  ('mission-be2-10-o1-c1', 'concept', 'A committed secret doesn''t need to be read anywhere in the code to already be exposed -- it''s exposed the moment it''s written to a file that gets committed.', 20, 2),
  ('mission-be2-10-o1-c1', 'solution', 'ev1: the password is hardcoded directly into the source file -- that''s the actual mistake. Everything else (repeated commits, the unused env var) just describes its blast radius.', 30, 3),
  ('mission-be2-10-o2-c1', 'orientation', 'Think about where this value now lives, not just who can currently see it.', 10, 1),
  ('mission-be2-10-o2-c1', 'solution', 'It''s baked into the repository''s history permanently, identical in every environment instead of per-environment, and readable by anyone with checkout access -- not just people with production access.', 20, 2),

  ('mission-be2-11-o1-c1', 'orientation', 'Nothing in this file ever checks whether port, databaseUrl, or notifyApiKey actually have values.', 10, 1),
  ('mission-be2-11-o1-c1', 'concept', 'listen() will happily be called with undefined, and the callback still fires -- ''the callback ran'' isn''t the same claim as ''the server is correctly configured.''', 20, 2),
  ('mission-be2-11-o1-c1', 'solution', 'console.log("Server started"); fires unconditionally in the listen callback, regardless of whether any of the three config values it depends on actually exist.', 30, 3),
  ('mission-be2-11-o2-c1', 'orientation', 'The problem isn''t any single missing variable -- it''s that nothing checks for one.', 10, 1),
  ('mission-be2-11-o2-c1', 'solution', 'Validate all required configuration once, at startup, and refuse to start (loudly) if any of it is missing or malformed -- catching it there beats discovering it mid-request, or worse, not at all.', 20, 2),

  ('mission-be2-12-o1-c1', 'orientation', 'The log doesn''t show a crash. Look for what''s different between ''started successfully'' and ''started successfully on the right port.''', 10, 1),
  ('mission-be2-12-o1-c1', 'solution', 'ev2: process.env.PORT is read before dotenv.config() has actually loaded the .env file, so port is undefined at the moment it matters -- that''s what makes the process ''succeed'' while landing nowhere near 8080.', 20, 2),
  ('mission-be2-12-o2-c1', 'orientation', 'Reorder the two lines in your head: which one needs the other to have already run?', 10, 1),
  ('mission-be2-12-o2-c1', 'concept', 'dotenv.config() is what actually populates process.env from the .env file. Anything that reads process.env before that call runs sees whatever was already there -- often nothing.', 20, 2),
  ('mission-be2-12-o2-c1', 'solution', 'const port = process.env.PORT; executes on line one, three lines before dotenv.config() ever loads the .env file -- port is captured as undefined and never revisited.', 30, 3),
  ('mission-be2-12-o3-c1', 'orientation', 'EADDRINUSE is a specific, loud failure. Compare it against what the log actually shows.', 10, 1),
  ('mission-be2-12-o3-c1', 'solution', 'A real port conflict throws an EADDRINUSE error and typically ends the process immediately. This log shows a clean, error-free startup message -- pointing at a listener that bound successfully, just not where anyone expected.', 20, 2),
  ('mission-be2-12-o4-c1', 'orientation', 'Look at what all three findings point at together: not a crash, not a conflict, just a read that happened too early.', 15, 1),
  ('mission-be2-12-o4-c1', 'solution', 'Call dotenv.config() before anything reads process.env, and never let a listen() callback log success without knowing the config value it actually bound to -- an unbound or wrongly-bound server should never be able to report a clean startup.', 25, 2);
